# owner: platform
"""Weekly timesheet rows, one line of text per worker."""

from typing import Dict, Iterable, List, Tuple

from hourglass.models import Shift
from hourglass.errors import ProjectError


def _tally(shifts: Iterable[Shift]) -> Dict[str, Tuple[int, int]]:
    totals = {}
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("shift has a blank worker name")
        count, mins = totals.get(shift.worker, (0, 0))
        totals[shift.worker] = (count + 1, mins + shift.span.minutes)
    return totals


# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, most hours first. ProjectError on bad input."""
    if not shifts:
        raise ProjectError("no shifts to total")
    rows = sorted(_tally(shifts).items(), key=lambda item: (-item[1][1], item[0]))
    return [f"{name}: {count} shifts, {mins / 60:.1f} hours" for name, (count, mins) in rows]
